function recurrence(coefs, init, n) {
  var a = init.slice();
  while (a.length <= n) {
    var i = a.length, s = 0;
    for (var k = 0; k < coefs.length; k++) s += coefs[k] * a[i - 1 - k];
    a.push(s);
  }
  return a[n];
}

function climbWays(n, steps) {
  var w = [1], i;
  for (i = 1; i <= n; i++) {
    var s = 0;
    for (var j = 0; j < steps.length; j++) if (i - steps[j] >= 0) s += w[i - steps[j]];
    w.push(s);
  }
  return w[n];
}
